    "description": "Requesting a refill for prescription rx_40817 (lisinopril 10 mg) for patient pt_4471 with quantity 30 and shipping address '220 Maple Street, Columbus, OH 43215'"
  },
  "applicable_norms": [
    {
      "policy_source_id": "q25",
      "interpretation": "A refill can only be requested if the prescription status is 'active', refills_remaining is at least 1, the current date is not after the expiry_date, and at least 75% of the days_supply has elapsed since the last_fill_date.",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q25",
      "interpretation": "The quantity of a refill must equal the quantity_per_fill of the prescription.",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q25",
      "interpretation": "The ship_to argument of request_refill must match the address on file for the patient.",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q25",
      "interpretation": "Explicit user confirmation must be obtained before any action that changes data (e.g., request_refill).",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q25",
      "interpretation": "Prescriptions with schedule 'C-II' cannot be refilled through this channel. This prescription has schedule 'none', so this does not apply.",
      "modality": "FORBID"
